private updateHud(): void {
  this.scoreText.setText(String(this.score))
  if (this.scorePulse > 0) {
    this.scorePulse = Math.max(0, this.scorePulse - 0.06)
    this.scoreText.setScale(1 + this.scorePulse * 0.2)
  }
  this.refreshHud()
}

